using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Sets the text shown in the chat with a bot if the chat is empty. Can be called only if userTypeBot.can_be_edited == true
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetBotInfoDescriptionAsync(long botUserId = default, string languageCode = default, string description = default)
    {

           using var activity =  StartCallActivity("SetBotInfoDescriptionAsync", typeof(SetBotInfoDescription).FullName ?? "SetBotInfoDescriptionAsync");

           try
           {
             return client.SetBotInfoDescriptionAsync(botUserId, languageCode, description);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
